fn print_hex_u64(mut n: u64) {
    let mut digits = [0u8; 16];
    let mut count = 0;
    let mut temp = n;

    while temp > 0 {
        let digit = (temp & 0xF) as u8;
        digits[count] = if digit < 10 { b'0' + digit } else { b'a' + digit - 10 };
        temp >>= 4;
        count += 1;
    }

    if count == 0 {
        crate::ffi::put_char(b'0');
    } else {
        for i in (0..count).rev() {
            crate::ffi::put_char(digits[i]);
        }
    }
}

fn print_hex_float(f: f64) {
    if f.is_nan() {
        for &ch in b"nan" {
            crate::ffi::put_char(ch);
        }
        return;
    }

    let bits = f.to_bits();
    let sign_bit = bits >> 63;
    let exponent = ((bits >> 52) & 0x7FF) as i32;
    let mantissa = bits & 0xFFFFFFFFFFFFF;

    if sign_bit == 1 {
        crate::ffi::put_char(b'-');
    }

    if exponent == 0x7FF {
        for &ch in b"inf" {
            crate::ffi::put_char(ch);
        }
        return;
    }

    for &ch in b"0x" {
        crate::ffi::put_char(ch);
    }

    if exponent == 0 && mantissa == 0 {
        crate::ffi::put_char(b'0');
        for &ch in b"p+0" {
            crate::ffi::put_char(ch);
        }
        return;
    }

    if exponent == 0 {
        for &ch in b"0p-1022" {
            crate::ffi::put_char(ch);
        }
        return;
